PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS User (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, passwordHash TEXT NOT NULL, name TEXT NOT NULL, handle TEXT NOT NULL UNIQUE, bio TEXT NOT NULL DEFAULT '', image TEXT, location TEXT, showLocation INTEGER NOT NULL DEFAULT 0, interests TEXT NOT NULL DEFAULT '[]', role TEXT NOT NULL DEFAULT 'member', membership TEXT NOT NULL DEFAULT 'free', createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Post (id TEXT PRIMARY KEY, body TEXT NOT NULL, imageUrl TEXT, linkUrl TEXT, topic TEXT, episode INTEGER, authorId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Comment (id TEXT PRIMARY KEY, body TEXT NOT NULL, postId TEXT NOT NULL REFERENCES Post(id) ON DELETE CASCADE, authorId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, parentId TEXT REFERENCES Comment(id), createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Like" (userId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, postId TEXT NOT NULL REFERENCES Post(id) ON DELETE CASCADE, PRIMARY KEY(userId,postId));
CREATE TABLE IF NOT EXISTS Bookmark (userId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, postId TEXT NOT NULL REFERENCES Post(id) ON DELETE CASCADE, PRIMARY KEY(userId,postId));
CREATE TABLE IF NOT EXISTS Follow (followerId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, followingId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'accepted', createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(followerId,followingId));
CREATE TABLE IF NOT EXISTS Block (blockerId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, blockedId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, PRIMARY KEY(blockerId,blockedId));
CREATE TABLE IF NOT EXISTS Message (id TEXT PRIMARY KEY, body TEXT NOT NULL, senderId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, recipientId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, readAt DATETIME, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Notification (id TEXT PRIMARY KEY, type TEXT NOT NULL, text TEXT NOT NULL, recipientId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, actorId TEXT REFERENCES User(id), href TEXT, readAt DATETIME, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Report (id TEXT PRIMARY KEY, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', reporterId TEXT NOT NULL REFERENCES User(id) ON DELETE CASCADE, postId TEXT REFERENCES Post(id) ON DELETE CASCADE, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS PasswordReset (id TEXT PRIMARY KEY, userId TEXT NOT NULL, tokenHash TEXT NOT NULL UNIQUE, expiresAt DATETIME NOT NULL, usedAt DATETIME, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS Post_createdAt_idx ON Post(createdAt DESC);
CREATE INDEX IF NOT EXISTS Message_pair_idx ON Message(senderId,recipientId,createdAt);
CREATE INDEX IF NOT EXISTS Notification_recipient_idx ON Notification(recipientId,createdAt DESC);
